def test_duplicate(array):
    """Return True if the array contains any duplicate element, else False."""
    return len(array) != len(set(array))

def is_woodall(n: int) -> bool:
    """Return True if n is a Woodall number (n = k * 2**k - 1 for k >= 1)."""
    if not isinstance(n, int) or n < 1:
        return False

    k = 1
    while True:
        woodall = k * (1 << k) - 1
        if woodall == n:
            return True
        if woodall > n:
            return False
        k += 1

def check(number):
    """Return True if number is one less than twice its digit reversal."""
    if number < 0:
        reverse = -int(str(-number)[::-1])
    else:
        reverse = int(str(number)[::-1])

    return number == 2 * reverse - 1

def find_Max_Num(digits):
    """Return the largest number that can be formed from the given digits."""
    if not digits:
        return 0
    return int("".join(str(d) for d in sorted(digits, reverse=True)))


if __name__ == "__main__":
