def recursive_list_sum(data):
    """Flatten a nested list and return the sum of all its elements."""
    total = 0
    for item in data:
        if isinstance(item, (list, tuple)):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def pos_count(numbers):
    """Return the number of positive numbers in the given list."""
    return sum(1 for number in numbers if number > 0)


if __name__ == "__main__":
