def bell_number(n: int) -> int:
    """Return the n-th Bell number (the number of partitions of an n-element set).

    Uses the Bell triangle, which computes all Bell numbers up to ``n`` in
    O(n^2) time and O(n) space.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1

    # The first entry of each row is the Bell number for that row.
    row = [1]
    for i in range(1, n + 1):
        next_row = [row[-1]]
        for value in row:
            next_row.append(next_row[-1] + value)
        row = next_row

    return row[0]

def is_Monotonic(array):
    """Return True if the array is monotonic (non-increasing or non-decreasing)."""
    if len(array) <= 1:
        return True

    increasing = True
    decreasing = True

    for i in range(1, len(array)):
        if array[i] > array[i - 1]:
            decreasing = False
        elif array[i] < array[i - 1]:
            increasing = False

        if not increasing and not decreasing:
            return False

    return True

def is_sublist(lst, sublist):
    """Return True if sublist appears as a contiguous slice of lst."""
    n = len(sublist)
    if n == 0:
        return True
    return any(lst[i:i + n] == sublist for i in range(len(lst) - n + 1))

def get_equal(tuples):
    """Return True if all given tuples have the same length, else False."""
    if not tuples:
        return True
    first_length = len(tuples[0])
    return all(len(t) == first_length for t in tuples)


if __name__ == "__main__":
    assert get_equal([(11, 22, 33), (44, 55, 66)]) == True
    assert get_equal([(1, 2), (3, 4, 5)]) == False
    assert get_equal([]) == True
    print("All tests passed")

def is_samepatterns(colors, patterns):
    """Return True if ``colors`` follows the same equality pattern as ``patterns``.

    Each distinct value in ``colors`` must correspond to exactly one distinct
    value in ``patterns``, and vice versa.
    """
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

    return True

def find_tuples(tuples_list, k):
    """Return the tuples whose every element is divisible by k."""
    return [tup for tup in tuples_list if all(element % k == 0 for element in tup)]


if __name__ == "__main__":
    assert find_tuples([(6, 24, 12), (7, 9, 6), (12, 18, 21)], 6) == [(6, 24, 12)]
    print("All tests passed")

def sequence(n):
    """Return the nth term of the Newman-Conway sequence (1-indexed)."""
    if n < 1:
        raise ValueError("n must be a positive integer")

    # a[1] = a[2] = 1
    a = [0, 1, 1]
    for i in range(3, n + 1):
        a.append(a[a[i - 1]] + a[i - a[i - 1]])

    return a[n]

def centered_hexagonal_number(n):
    """Return the nth centered hexagonal number."""
    return 3 * n * (n - 1) + 1


if __name__ == "__main__":
    assert centered_hexagonal_number(10) == 271
    print(centered_hexagonal_number(10))

def freq_count(lst):
    """Return a dictionary mapping each element in lst to its frequency."""
    counts = {}
    for item in lst:
        counts[item] = counts.get(item, 0) + 1
    return counts

def closest_num(n):
    """Return the closest number smaller than n."""
    return n - 1


if __name__ == "__main__":
    assert closest_num(11) == 10
