def decimal_to_binary(n: int) -> str:
    """Return the binary representation of a decimal integer without leading zeros."""
    if n == 0:
        return "0"

    sign = ""
    if n < 0:
        sign = "-"
        n = -n

    digits = []
    while n > 0:
        digits.append("1" if n & 1 else "0")
        n >>= 1

    return sign + "".join(reversed(digits))

def next_smallest_palindrome(n: int) -> int:
    """Return the smallest palindrome strictly greater than n."""
    if n < 0:
        return 0

    s = str(n)
    length = len(s)

    # If n consists only of 9s, the next palindrome has one more digit.
    if all(ch == "9" for ch in s):
        return int("1" + "0" * (length - 1) + "1")

    # Mirror the left half to form the smallest palindrome with this prefix.
    half = s[: (length + 1) // 2]
    candidate = int(half + half[: length // 2][::-1])

    if candidate > n:
        return candidate

    # Otherwise, increase the left half and mirror it again.
    half = str(int(half) + 1)
    return int(half + half[: length // 2][::-1])

