def search(nums):
    """Return the element that appears only once in a sorted array.

    Every other element is assumed to appear exactly twice.
    """
    if not nums:
        raise ValueError("array must not be empty")

    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        if mid % 2 == 0:
            # The single element is after this pair if the pair is intact.
            if nums[mid] == nums[mid + 1]:
                left = mid + 2
            else:
                right = mid
        else:
            # The single element is after this pair if the pair is intact.
            if nums[mid] == nums[mid - 1]:
                left = mid + 1
            else:
                right = mid - 1

    return nums[left]

