def _sum_proper_divisors(n):
    """Return the sum of the proper divisors of n."""
    if n <= 1:
        return 0

    total = 1
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            total += divisor
            other = n // divisor
            if other != divisor:
                total += other
        divisor += 1
    return total


def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 through limit (inclusive)."""
    if limit < 1:
        return 0

    # divisor_sums[n] is the sum of the proper divisors of n.
    divisor_sums = [0] * (limit + 1)
    for divisor in range(1, limit // 2 + 1):
        for multiple in range(divisor * 2, limit + 1, divisor):
            divisor_sums[multiple] += divisor

    total = 0
    large_partner_sums = {}

    for number in range(2, limit + 1):
        partner = divisor_sums[number]
        if partner == number:
            continue

        if partner <= limit:
            partner_sum = divisor_sums[partner]
        else:
            if partner not in large_partner_sums:
                large_partner_sums[partner] = _sum_proper_divisors(partner)
            partner_sum = large_partner_sums[partner]

        if partner_sum == number:
            total += number

    return total

