import math


def angle_complex(real, imag=None):
    """Return the phase angle (in radians) of a complex number.

    The number may be supplied either as a single complex value, or as
    separate real and imaginary parts.  A complex value may also be given
    for either part (e.g. ``angle_complex(0, 1j)``), in which case the
    parts are combined before taking the angle.
    """
    if imag is None:
        return cmath.phase(real)

    if isinstance(real, complex) or isinstance(imag, complex):
        return cmath.phase(real + imag)

    return math.atan2(imag, real)

