def magic_square_test(matrix):
    """Return True if matrix is a magic square, otherwise False."""
    if not matrix:
        return False

    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False

    target = sum(matrix[0])
    if any(sum(row) != target for row in matrix):
        return False

    if any(sum(matrix[row][col] for row in range(n)) != target
           for col in range(n)):
        return False

    if sum(matrix[i][i] for i in range(n)) != target:
        return False
    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True

