def pancake_sort(arr):
    """Sort a list using the pancake sort algorithm.

    A flip reverses the order of the first k elements. For each position
    from the end down to the start, move the largest remaining element
    into place with at most two flips.
    """
    arr = list(arr)
    n = len(arr)

    def flip(k):
        arr[:k] = reversed(arr[:k])

    for size in range(n, 1, -1):
        # Find the largest element in the unsorted prefix.
        max_index = 0
        for i in range(1, size):
            if arr[i] > arr[max_index]:
                max_index = i

        if max_index == size - 1:
            continue

        # Bring the largest element to the front, then flip it into place.
        if max_index != 0:
            flip(max_index + 1)
        flip(size)

    return arr

