def get_total_number_of_sequences(m: int, n: int) -> int:
    """Count length-n sequences in [1, m] where each term is at least twice the previous."""
    if m <= 0 or n <= 0:
        return 0

    # dp[x] is the number of valid sequences of the current length ending in x.
    dp = [1] * (m + 1)
    dp[0] = 0

    for _ in range(1, n):
        # prefix[x] = dp[1] + ... + dp[x]
        prefix = [0] * (m + 1)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]

        # A new value x can follow any previous value y <= x // 2.
        dp = [0] + [prefix[x // 2] for x in range(1, m + 1)]

    return sum(dp)


