def max_sum(arr):
    """Return the maximum sum of a bitonic subsequence of ``arr``.

    A bitonic subsequence first increases and then decreases.  The peak
    element belongs to both parts, so it is subtracted once when combining
    the increasing and decreasing sums.
    """
    n = len(arr)
    if n == 0:
        return 0

    # inc[i]: maximum sum of an increasing subsequence ending at i.
    inc = list(arr)
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i]: maximum sum of a decreasing subsequence starting at i.
    dec = list(arr)
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    return max(inc[i] + dec[i] - arr[i] for i in range(n))

def lps(s: str) -> int:
    """Return the length of the longest palindromic subsequence of s."""
    n = len(s)
    if n < 2:
        return n

    # prev[j] stores the LPS length for the substring starting at i + 1
    # and ending at j. Only two rows are needed at any time.
    prev = [0] * n
    for i in range(n - 1, -1, -1):
        curr = [0] * n
        curr[i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                curr[j] = prev[j - 1] + 2
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr

    return prev[n - 1]

