def count_Primes_nums(n):
    """Return the number of prime numbers strictly less than n."""
    if n < 3:
        return 0

    # Sieve of Eratosthenes: is_prime[i] is True for primes below n.
    is_prime = bytearray(b"\x01") * n
    is_prime[0:2] = b"\x00\x00"

    for p in range(2, int(n ** 0.5) + 1):
        if is_prime[p]:
            # Mark multiples of p starting at p * p.
            is_prime[p * p:n:p] = b"\x00" * (((n - 1 - p * p) // p) + 1)

    return sum(is_prime)

