def max_sum_increasing_subseq(a, n, i, k):
    """Return the maximum sum of an increasing subsequence that uses a[k].

    The subsequence may only use elements from the prefix a[0..i] before
    appending a[k].  All chosen prefix elements must be smaller than a[k].
    """
    # dp[j] = maximum sum of an increasing subsequence ending at a[j]
    # using only indices from 0 through i.
    dp = [0] * n
    for j in range(i + 1):
        dp[j] = a[j]
        for p in range(j):
            if a[p] < a[j]:
                dp[j] = max(dp[j], dp[p] + a[j])

    best_prefix = 0
    for j in range(i + 1):
        if a[j] < a[k]:
            best_prefix = max(best_prefix, dp[j])

    return best_prefix + a[k]

