def set_left_most_unset_bit(n: int) -> int:
    """Set the leftmost unset bit in the binary representation of n.

    If all bits up to the most significant set bit are already set, the next
    higher bit is set instead.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    # Mask covering all bit positions up to the most significant set bit.
    mask = (1 << n.bit_length()) - 1
    unset_bits = (~n) & mask

    if unset_bits:
        # Highest unset bit within the current binary representation.
        return n | (1 << (unset_bits.bit_length() - 1))

    # All bits are set, so set the next higher bit.
    return n | (1 << n.bit_length())

