def sumofFactors(n):
    """Return the sum of all even factors of a positive integer n."""
    if n <= 0:
        return 0

    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            other = n // i
            if i % 2 == 0:
                total += i
            if other != i and other % 2 == 0:
                total += other
        i += 1

    return total

