def bell_Number(n):
    """Return the nth Bell number (the number of partitions of an n-element set)."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    # Build Bell's triangle. The first entry of each row is the Bell number
    # for that row, and every other entry is the sum of the entry to its left
    # and the entry directly above-left.
    row = [1]
    for i in range(1, n + 1):
        new_row = [row[-1]]
        for j in range(1, i + 1):
            new_row.append(new_row[j - 1] + row[j - 1])
        row = new_row

    return row[0]

