def largest_subset(numbers):
    """Return the size of the largest subset in which every pair is divisible.

    For every pair (a, b) in the subset, either a divides b or b divides a.
    Sorting the numbers lets us find the longest divisibility chain with DP.
    """
    if not numbers:
        return 0

    numbers = sorted(numbers)
    dp = [1] * len(numbers)

    for i in range(len(numbers)):
        for j in range(i):
            if numbers[i] % numbers[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def get_median(ar1, ar2, n):
    """Return the median of two sorted lists of the same size."""
    if n == 0:
        return 0.0

    # Binary search for the partition point in the first list.
    low, high = 0, n
    while low <= high:
        cut1 = (low + high) // 2
        cut2 = n - cut1

        left1 = ar1[cut1 - 1] if cut1 > 0 else float("-inf")
        right1 = ar1[cut1] if cut1 < n else float("inf")
        left2 = ar2[cut2 - 1] if cut2 > 0 else float("-inf")
        right2 = ar2[cut2] if cut2 < n else float("inf")

        if left1 <= right2 and left2 <= right1:
            return (max(left1, left2) + min(right1, right2)) / 2.0
        elif left1 > right2:
            high = cut1 - 1
        else:
            low = cut1 + 1

    raise ValueError("Input lists must be sorted")

