def heap_sort(arr):
    """Return a new list containing the elements of *arr* in sorted order."""
    result = list(arr)
    n = len(result)

    def sift_down(start, end):
        root = start
        while True:
            child = 2 * root + 1
            if child > end:
                break
            if child + 1 <= end and result[child] < result[child + 1]:
                child += 1
            if result[root] < result[child]:
                result[root], result[child] = result[child], result[root]
                root = child
            else:
                break

    # Build a max-heap.
    for start in range((n - 2) // 2, -1, -1):
        sift_down(start, n - 1)

    # Repeatedly move the maximum to the end of the unsorted portion.
    for end in range(n - 1, 0, -1):
        result[0], result[end] = result[end], result[0]
        sift_down(0, end - 1)

    return result

