    """Toggle every bit of n except the most significant and least significant bits."""
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    bit_length = n.bit_length()
    if bit_length <= 2:
        return n

    # Bits at positions 1 through bit_length - 2 (0-indexed from the right).
    middle_mask = ((1 << (bit_length - 1)) - 1) & ~1
    return n ^ middle_mask


