def is_polite(n):
    """Return the n-th polite number (1-indexed).

    A polite number is a positive integer that can be written as the sum of
    two or more consecutive positive integers. Equivalently, polite numbers
    are all positive integers except powers of two.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    def polite_count(x):
        # Number of powers of two in [1, x] is floor(log2(x)) + 1.
        return x - (x.bit_length())

    # Find the smallest x such that there are at least n polite numbers <= x.
    low, high = 1, 2 * n + 1
    while low < high:
        mid = (low + high) // 2
        if polite_count(mid) >= n:
            high = mid
        else:
            low = mid + 1
    return low

