import ast


def tuple_str_int(tuple_string):
    """Return the integer tuple represented by *tuple_string*.

    Examples:
        >>> tuple_str_int("(7, 8, 9)")
        (7, 8, 9)
    """
    value = ast.literal_eval(tuple_string)

    if isinstance(value, (tuple, list)):
        return tuple(int(item) for item in value)

    return (int(value),)

from bisect import bisect_right


def right_insertion(sorted_list, value):
    """Return the rightmost insertion index for value in sorted_list."""
    return bisect_right(sorted_list, value)

def new_tuple(lst, string):
    """Create a new tuple from the given list and string."""
    return tuple(lst) + (string,)

def even_position(numbers):
    """Return True if every element at an even index is even."""
    return all(number % 2 == 0 for number in numbers[::2])


if __name__ == "__main__":
    assert even_position([3, 2, 1]) == False
    assert even_position([2, 3, 4]) == True
    assert even_position([]) == True
    print("All tests passed")

def remove_nested(tup):
    """Return a tuple with all tuple elements removed."""
    return tuple(item for item in tup if not isinstance(item, tuple))


if __name__ == "__main__":
    assert remove_nested((1, 5, 7, (4, 6), 10)) == (1, 5, 7, 10)
    print("All tests passed")

def count_list(input_list):
    """Return the number of lists contained in the given list of lists."""
    return len(input_list)


if __name__ == "__main__":
    assert count_list([[1, 3], [5, 7], [9, 11], [13, 15, 17]]) == 4
    print("All tests passed")

def return_sum(dictionary):
    """Return the sum of all values in the given dictionary."""
    return sum(dictionary.values())


if __name__ == "__main__":
    assert return_sum({'a': 100, 'b': 200, 'c': 300}) == 600
    print("All tests passed")

def remove_all_spaces(s):
    """Remove all whitespace characters from a string."""
    return ''.join(s.split())

def test_three_equal(x, y, z):
    """Return the number of equal values among three integers.

    If all three are equal, return 3. If exactly two are equal, return 2.
    Otherwise, return 0.
    """
    if x == y == z:
        return 3
    if x == y or x == z or y == z:
        return 2
    return 0

import math


def is_perfect_square(number):
    """Return True if number is a perfect square, otherwise False."""
    if isinstance(number, float):
        if not number.is_integer():
            return False
        number = int(number)

    if not isinstance(number, int) or number < 0:
        return False

    root = math.isqrt(number)
    return root * root == number

def is_product_even(numbers):
    """Return True if the product of the numbers in the list is even."""
    return any(number % 2 == 0 for number in numbers)


assert is_product_even([1, 2, 3])

def max_sum_list(lists):
    """Return the sublist whose elements have the greatest sum.

    If multiple sublists have the same sum, the first one is returned.
    An empty input returns an empty list.
    """
    if not lists:
        return []
    return max(lists, key=sum)

def max_run_uppercase(s: str) -> int:
    """Return the length of the longest consecutive run of uppercase letters."""
    longest = current = 0
    for char in s:
        if char.isupper():
            current += 1
            longest = max(longest, current)
        else:
            current = 0
    return longest

def first_odd(numbers):
    """Return the first odd number in the list, or None if there is none."""
    for number in numbers:
        if number % 2 != 0:
            return number
    return None

def check_smaller(first, second):
    """Return True if every element of ``second`` is smaller than the
    corresponding element of ``first``."""
    return all(b < a for a, b in zip(first, second))
